mapper.select:
select pp.supplier_id, s.name as supplierName, pph.currency, pph.tax_price as taxPrice, pph.tax_rate * 100 as taxRate, pph.min_qty as minQty, pph.max_qty as maxQty, pph.delivery_day as deliveryDay from purchase_price pp left join purchase_price_detail ppd on pp.id = ppd.purchase_price_id and ppd.is_deleted = false inner join purchase_price_history pph on pp.id = pph.purchase_price_id and pph.is_deleted = false left join supplier s on pp.supplier_id = s.id and s.is_deleted = false
pp.is_deleted = false and pp.approve_status = 'approve' and ppd.disabled = false and now() >= pph.effective_date and pph.expire_date >= now()
and pph.sku_id = #{params.skuId}
and pph.max_qty >= #{params.purchaseQty} and #{params.purchaseQty} > pph.min_qty
and pp.supplier_id = #{params.supplierId}
